{
 static BusinessColumnSchema C(string n,string l,string d,string t,bool tenant=false,bool computed=false,string[]? trueConcepts=null)=>new(n,l,d,t,tenant,computed,trueConcepts);
 static BusinessTableSchema T(string n,string l,string d,string[] concepts,params BusinessColumnSchema[] columns)=>new(n,l,d,concepts,columns);
 static readonly BusinessSchema Schema=new([
  T("Customers","Customers","Customers in the current organization.",["customer","client","buyer"],C("Id","Customer ID","Identifier","Integer"),C("Name","Customer","Full name","String",computed:true),C("FirstName","First name","First name","String"),C("LastName","Last name","Last name","String"),C("Email","Email","Email address","String"),C("CreatedAt","Created","Creation date","Date"),C("OrganizationId","Organization ID","Internal tenant key","Guid",true)),
  T("Products","Products","Products sold by the organization.",["product","sku","item","merchandise"],C("Id","Product ID","Identifier","Integer"),C("Sku","SKU","Stock keeping unit","String"),C("Name","Product","Product name","String"),C("UnitPrice","Unit price","Trusted unit price","Money"),C("IsActive","Active","Active state","Boolean"),C("Inventory.QuantityOnHand","Quantity on hand","Available inventory quantity","Number"),C("Inventory.ReorderLevel","Reorder level","Inventory replenishment threshold","Number"),C("Inventory.IsLowStock","Low stock","Trusted .NET state; constrain with Equals true when low stock or reordering is requested","Boolean",computed:true,trueConcepts:["low stock","need reordering","needs reordering","reorder","below reorder level"]),C("CreatedAt","Created","Creation date","Date"),C("OrganizationId","Organization ID","Internal tenant key","Guid",true)),
  T("Orders","Orders","Customer orders.",["order","purchase","fulfillment","shipment"],C("Id","Order ID","Identifier","Integer"),C("OrderNumber","Order number","Human-readable number","String"),C("CustomerId","Customer ID","Customer identifier","Integer"),C("Customer.Name","Customer","Customer name","String"),C("Status","Status","Order status","String"),C("TotalAmount","Total","Trusted order total","Money"),C("CreatedAt","Created","Creation date","Date"),C("OrganizationId","Organization ID","Internal tenant key","Guid",true)),
  T("OrderItems","Order items","Order line items.",["order item","ordered product","top selling"],C("Id","Order item ID","Identifier","Integer"),C("OrderId","Order ID","Parent order","Integer"),C("ProductId","Product ID","Product identifier","Integer"),C("Product.Name","Product","Product name","String"),C("Description","Description","Line description","String"),C("Quantity","Quantity","Ordered quantity","Number"),C("UnitPrice","Unit price","Recorded price","Money"),C("LineTotal","Line total","Trusted line total","Money"),C("OrganizationId","Organization ID","Internal tenant key","Guid",true)),
  T("Invoices","Invoices","Customer invoices.",["invoice","billing","bill","due","overdue","outstanding","paid","sales","revenue"],C("Id","Invoice ID","Identifier","Integer"),C("InvoiceNumber","Invoice number","Human-readable number","String"),C("CustomerId","Customer ID","Customer identifier","Integer"),C("Customer.Name","Customer","Customer name","String"),C("Status","Status","Invoice status","String"),C("IssueDate","Issue date","Issue date","Date"),C("DueDate","Due date","Due date","Date"),C("TotalAmount","Total","Trusted total","Money"),C("PaidAmount","Paid","Recorded payments","Money",computed:true),C("OutstandingBalance","Outstanding balance","Trusted unpaid balance","Money",computed:true),C("IsOverdue","Overdue","Trusted overdue state","Boolean",computed:true),C("IsFullyPaid","Fully paid","Trusted paid state","Boolean",computed:true),C("OrganizationId","Organization ID","Internal tenant key","Guid",true)),
