public sealed class BusinessSchemaSelector(IBusinessSchemaService schemas):IBusinessSchemaSelector
{
 public BusinessSchema Select(string question){var s=schemas.GetSchema();var q=Regex.Replace(question.ToLowerInvariant(),"[^a-z0-9]+"," ");var scored=s.Entities.Select(e=>new{E=e,S=Score(e,q)}).OrderByDescending(x=>x.S).ThenBy(x=>x.E.Name).ToList();var chosen=scored.Where(x=>x.S>0).Take(4).Select(x=>x.E).ToList();if(chosen.Count==0)chosen=s.Entities.Take(4).ToList();foreach(var r in s.Relationships.Where(r=>chosen.Any(e=>e.Name==r.FromEntity)&&RelationshipScore(r,q)>0).OrderByDescending(r=>RelationshipScore(r,q)).ToList()){var target=s.Entities.FirstOrDefault(x=>x.Name==r.ToEntity);if(target is not null&&chosen.Count<4&&!chosen.Contains(target))chosen.Add(target);}var requested=scored.Where(x=>x.S>0).Select(x=>x.E.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);for(var pass=0;pass<3&&chosen.Count<4;pass++){var bridge=s.Relationships.FirstOrDefault(r=>chosen.Any(e=>e.Name==r.FromEntity)&&!chosen.Any(e=>e.Name==r.ToEntity)&&(requested.Contains(r.ToEntity)||CanReach(r.ToEntity,requested,s.Relationships,2-pass)));if(bridge is null)break;var target=s.Entities.FirstOrDefault(x=>x.Name==bridge.ToEntity);if(target is not null)chosen.Add(target);}var names=chosen.Select(x=>x.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);return new(chosen,s.Relationships.Where(r=>names.Contains(r.FromEntity)&&names.Contains(r.ToEntity)).ToList());}
 static int Score(BusinessTableSchema e,string q)=>Terms(e.Name,e.DisplayName,e.Description).Sum(x=>q.Contains(x)?2:0)+e.Concepts.Sum(x=>q.Contains(x.ToLowerInvariant())?3:0)+e.Columns.Sum(c=>Terms(c.Name,c.DisplayName,c.Description).Sum(x=>q.Contains(x)?1:0)+(c.Concepts?.Sum(x=>q.Contains(x.ToLowerInvariant())?2:0)??0));
 static IEnumerable<string> Terms(params string[] values)=>values.SelectMany(x=>Regex.Replace(x.ToLowerInvariant(),"[^a-z0-9]+"," ").Split(' ',StringSplitOptions.RemoveEmptyEntries)).Where(x=>x.Length>2).Distinct();
 static int RelationshipScore(BusinessRelationshipSchema r,string q)=>Terms(r.Name??"",r.Description??"",r.ToEntity).Sum(x=>q.Contains(x)?2:0)+(r.Concepts?.Sum(x=>q.Contains(x.ToLowerInvariant())?3:0)??0);
 static bool CanReach(string start,HashSet<string> targets,IReadOnlyList<BusinessRelationshipSchema> relationships,int depth)=>depth>=0&&(targets.Contains(start)||relationships.Where(x=>x.FromEntity.Equals(start,StringComparison.OrdinalIgnoreCase)).Any(x=>CanReach(x.ToEntity,targets,relationships,depth-1)));
}
